<?php
$activeLogo = site_setting('logo_path');
$reviewTotals = db()->query("SELECT COUNT(*) AS total,SUM(statut='en_attente') AS pending,AVG(CASE WHEN statut='publie' THEN note END) AS average FROM avis_terrains")->fetch();
$terrainRatings = db()->query("SELECT t.id,t.titre,AVG(a.note) AS average,COUNT(a.id) AS total FROM terrains t LEFT JOIN avis_terrains a ON a.terrain_id=t.id AND a.statut='publie' GROUP BY t.id,t.titre HAVING COUNT(a.id)>0 ORDER BY average DESC")->fetchAll();
$projectRatings = db()->query("SELECT r.id,r.titre,AVG(a.note) AS average,COUNT(a.id) AS total FROM realisations r LEFT JOIN avis_terrains a ON a.realisation_id=r.id AND a.statut='publie' GROUP BY r.id,r.titre HAVING COUNT(a.id)>0 ORDER BY average DESC")->fetchAll();
$typedProperties = db()->query('SELECT id,titre,type_bien FROM terrains ORDER BY date_publication DESC LIMIT 50')->fetchAll();
$reviews = db()->query('SELECT a.*,t.titre AS terrain_titre,r.titre AS realisation_titre FROM avis_terrains a LEFT JOIN terrains t ON t.id=a.terrain_id LEFT JOIN realisations r ON r.id=a.realisation_id ORDER BY FIELD(a.statut,"en_attente","publie","masque"),a.date_creation DESC LIMIT 100')->fetchAll();
?>
<div class="admin-shell admin-addons">
  <section class="admin-section branding-panel"><div class="admin-section-title"><div><span class="eyebrow">IDENTITÉ DU SITE</span><h2>Paramètres du site / Branding</h2></div></div><div class="branding-layout"><div class="branding-preview"><?php if ($activeLogo): ?><img src="?page=logo&amp;v=<?= e(substr($activeLogo,0,8)) ?>" alt="Logo actuellement actif"><?php else: ?><span class="brand-mark">SG</span><?php endif; ?><div><strong>Logo actif</strong><small>En-tête · pied de page · fiches PDF</small></div></div><form method="post" enctype="multipart/form-data" class="branding-form"><?= csrf_field() ?><input type="hidden" name="action" value="save_branding"><label>Nouveau logo<input type="file" name="logo" accept="image/png,image/jpeg,image/svg+xml,.png,.jpg,.jpeg,.svg" required><small>PNG, JPG ou SVG sécurisé · 2 Mo maximum.</small></label><button class="button button-green">Enregistrer le logo <span>↗</span></button></form></div></section>
  <section class="admin-section"><div class="admin-section-title"><div><span class="eyebrow">CATÉGORISATION</span><h2>Types de biens au catalogue</h2></div></div><?php if ($typedProperties): ?><div class="type-admin-list"><?php foreach ($typedProperties as $property): ?><form method="post" class="type-admin-row"><?= csrf_field() ?><input type="hidden" name="action" value="update_land_type"><input type="hidden" name="id" value="<?= (int)$property['id'] ?>"><strong><?= e($property['titre']) ?></strong><select name="type_bien" aria-label="Type de <?= e($property['titre']) ?>"><?php foreach (['terrain'=>'Terrain','maison'=>'Maison','lot_loti'=>'Lot loti'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $property['type_bien']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="button button-outline">Enregistrer</button></form><?php endforeach; ?></div><?php else: ?><p class="admin-empty">Les catégories apparaîtront ici au fur et à mesure des publications.</p><?php endif; ?></section>
  <section class="admin-section" id="reviews"><div class="admin-section-title"><div><span class="eyebrow">MODÉRATION</span><h2>Avis et notes</h2></div><div class="review-admin-summary"><strong><?= (int)($reviewTotals['pending'] ?? 0) ?></strong><span>en attente</span><strong><?= number_format((float)($reviewTotals['average'] ?? 0),1,',',' ') ?> / 5</strong><span>moyenne publiée</span></div></div>
    <?php if ($terrainRatings || $projectRatings): ?><div class="rating-summary-grid"><?php foreach ($terrainRatings as $rating): ?><div class="rating-summary-item"><strong><?= e($rating['titre']) ?></strong><?= star_rating((float)$rating['average'],(int)$rating['total']) ?></div><?php endforeach; ?><?php foreach ($projectRatings as $rating): ?><div class="rating-summary-item"><strong><?= e($rating['titre']) ?> · Projet</strong><?= star_rating((float)$rating['average'],(int)$rating['total']) ?></div><?php endforeach; ?></div><?php endif; ?>
    <?php if ($reviews): ?><div class="moderation-list"><?php foreach ($reviews as $review): $targetLabel=$review['type_cible']==='terrain' ? ($review['terrain_titre'] ?? 'Terrain retiré') : ($review['type_cible']==='realisation' ? ($review['realisation_titre'] ?? 'Projet retiré') : str_replace('-',' ',(string)$review['cible_service'])); ?><article class="moderation-item"><div class="moderation-copy"><div class="review-card-head"><strong><?= e($review['nom']) ?></strong><?= star_rating((float)$review['note']) ?><span class="status-pill <?= e($review['statut']) ?>"><?= e(str_replace('_',' ',$review['statut'])) ?></span></div><p><b><?= e($targetLabel) ?></b> · <?= e(date('d/m/Y H:i',strtotime($review['date_creation']))) ?></p><p><?= nl2br(e($review['commentaire'])) ?></p></div><div class="moderation-actions"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="review_moderation"><input type="hidden" name="id" value="<?= (int)$review['id'] ?>"><select name="status" aria-label="État de modération"><option value="en_attente" <?= $review['statut']==='en_attente'?'selected':'' ?>>En attente</option><option value="publie" <?= $review['statut']==='publie'?'selected':'' ?>>Publier</option><option value="masque" <?= $review['statut']==='masque'?'selected':'' ?>>Masquer</option></select><button class="button button-outline">Appliquer</button></form><?php if (($_SESSION['user']['role'] ?? '')==='super_admin'): ?><form method="post" onsubmit="return confirm('Supprimer définitivement cet avis ?')"><?= csrf_field() ?><input type="hidden" name="action" value="delete_review"><input type="hidden" name="id" value="<?= (int)$review['id'] ?>"><button class="danger-link">Supprimer</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php else: ?><p class="admin-empty">Aucun avis reçu pour le moment.</p><?php endif; ?>
  </section>
</div>